INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES
('doc-new-book-1', 'book', 'book-new-1', 'new-book-1', 'عصر سرمایه‌داری نظارتی', 'The Age of Surveillance Capitalism: The Fight for a Human Future at the New Frontier of Power', 'book', 'بنیادی‌ترین منبع نظریِ مفهوم «سرمایه‌داری نظارتی» که در سایت به‌عنوان مدخل ۱۱۸ آمده است؛ Zuboff در آن قدرت‌های جدید داده‌محور، محصولات کنشی (actionable products) و بازارهای پیش‌بینی آینده‌رفتار را تحلیل می‌کند. بعداً در مقالات Big Other (2015) و Surveillance & Society (2019) گسترش یافت.', NULL, 'fa', NULL, 'international', '59f99d1ea94a5ef75bd45c2402d908ff76ad8e1ad41ac6a0248a66adb9242112', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-2', 'book', 'book-new-2', 'new-book-2', 'الگوریتم‌های سرکوب: چگونه موتورهای جستجو نژادپرستی را تقویت می‌کنند', 'Algorithms of Oppression: How Search Engines Reinforce Racism', 'book', 'بنیادی‌ترین منبع نقدِ الگوریتم‌های جستجو از منظر نژاد و جنسیت؛ پراستناد در مطالعات الگوریتم انتقادی و عدالت داده. این کتاب مستقیماً با مدخل ۲۸۱ (الگوریتم‌های سرکوب) هم‌نام است.', NULL, 'fa', NULL, 'international', '2a13be796bdc812739dc92f8aaadd657a054aab10be57f268faf6d816f919084', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-3', 'book', 'book-new-3', 'new-book-3', 'سرمایه‌داری پلتفرم', 'Platform Capitalism: The Politics of the Platform Economy', 'book', 'یکی از تأثیرگذارترین آثار مطالعات انتقادی اقتصاد پلتفرمی؛ تحلیل سرمایه‌گذاری‌های پلتفرمی، جریان‌های درآمدی و رقابت بین پلتفرم‌های بزرگ. پایه‌ی مفهومی مدخل ۲۲۲ (سرمایه‌داری پلتفرمی) و ۱۱۷ (جامعه پلتفرمی).', NULL, 'fa', NULL, 'international', '9272a68cf16b91769d54215e2e895d43ad38d57a6e158bc9f609b39be2fa566f', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-4', 'book', 'book-new-4', 'new-book-4', 'پسا-حقیقت', 'Post-truth', 'book', 'مهم‌ترین کتاب فلسفیِ مفهوم «پسا-حقیقت»؛ McIntyre استدلال می‌کند پسا-حقیقت وضعی طبیعی نیست، بلکه یک استراتژی گمراه‌سازی عمدی و سیستماتیک است. پایه‌ی نظریِ مدخل ۴۳۸ (عصر پسا-حقیقت) و ۶۷۳ (نظریه پستحقیقت).', NULL, 'fa', NULL, 'international', 'e4dc9215c84f00e825f143a4c9b19380dab066c7f73abd4b922324424f7583f2', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-5', 'book', 'book-new-5', 'new-book-5', 'پسا-حقیقت (نسخه‌ی د_آنکونا)', 'Post Truth', 'book', 'کتاب مرجعِ ژورنالیستیِ پسا-حقیقت؛ تحلیل تاریخچه‌ی مفهوم (از ۱۹۷۴ تا ۲۰۱۶) و نقش رسانه‌های دیجیتال و شبکه‌های اجتماعی در ساخت پسا-حقیقت. مکمل McIntyre و منبع اصلی مدخل ۵۳۰.', NULL, 'fa', NULL, 'international', '23e83ad38ce3f6eceec17d3b6ad0bbda3fcf5937e8c1ddf51fc16e399465248b', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-6', 'book', 'book-new-6', 'new-book-6', 'میم‌ها در فرهنگ دیجیتال', 'Memes in Digital Culture', 'book', 'مرجع‌ترین کتاب مطالعات میم‌ها؛ چارچوب «تولید معنایی میم‌ها» (meaning-making memes) و طبقه‌بندی میم‌های متحرک، ایستا و متنی. پایه‌ی مدخل ۳۳۰ (اثر هنری در عصر بازتولید مکانیکی — بازسازی و بازتولید دیجیتال).', NULL, 'fa', NULL, 'international', '6dbfb3e3849c155ccd25292c39d33cc00e0afb6310cce3996c1997ec327cabe5', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-7', 'book', 'book-new-7', 'new-book-7', 'فهمیدن فرهنگ دیجیتال', 'Understanding Digital Culture', 'book', 'کتاب درسیِ مرجعِ فرهنگ دیجیتال؛ تحلیل تغییرات هویت، مشارکت و جریان فرهنگی در عصر دیجیتال. پایه‌ی مفهومی مدخل ۲۲۵ (فرهنگ الگوریتمی) و ۱۱۷ (جامعه پلتفرمی).', NULL, 'fa', NULL, 'international', '0e06f7b807efefc0b84197ca29a2dc52fa13083acf269d3af8f52b84377b7ce9', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-8', 'book', 'book-new-8', 'new-book-8', 'اخبار جعلی', 'Fake News', 'book', 'کتاب مرجعِ ژورنالیستیِ اخبار جعلی؛ بررسی تاریخچه، پیدایش، اشکال و عواقب fake news با تأکید بر سیاست و انتخابات. مکمل تجربیِ مدخل‌های ۵۳۰، ۶۷۴ و ۷۰۵.', NULL, 'fa', NULL, 'international', 'd24ce51cda93e97284864466180e1f9877526922bd8760210791af33ea7ec8b7', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-9', 'book', 'book-new-9', 'new-book-9', 'تاجران توجه', 'The Attention Merchants: The Epic Scramble to Get Inside Your Head', 'book', 'مرجع‌ترین کتاب تاریخیِ «اقتصاد توجه»؛ از کافه‌های عصری تا گوگل، تاریخ رقابت بر سر توجه انسان را روایت می‌کند. مکمل مدخل‌های ۳۲ (اقتصاد توجه) و ۳۸۳/۵۰۲ (تاجران توجه).', NULL, 'fa', NULL, 'international', '329ff2830dd1aede62a1831724ab0c44ceb9f38a43a39aebbde7fe4f985abf0c', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-10', 'book', 'book-new-10', 'new-book-10', 'حباب فیلتر', 'The Filter Bubble: What the Internet Hides from You', 'book', 'مرجع‌ترین کتابِ مفهوم «حباب فیلتر»؛ پارایزر نشان می‌دهد الگوریتم‌های شخصی‌سازی اینترنت چگونه هر کاربر را در دنیای اطلاعاتی جداگانه‌ای محصور می‌کنند. پایه‌ی مدخل ۱۱۲ (حباب فیلتر) و ۱۱۳ (اتاق پژواک).', NULL, 'fa', NULL, 'international', '3468441e19949933adee5ba0fd19388e7224e30fe40084f655096ef63554e90a', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-11', 'article', 'book-new-11', 'new-book-11', 'پخش اخبار درست و نادرست در فضای آنلاین', 'The spread of true and false news online', 'article', 'پراستنادترین مقاله‌ی تجربیِ مقایسه‌ی انتشار اخبار درست و نادرست در Twitter؛ یافته‌ی محوری: اخبار نادرست حدود ۶ برابر سریع‌تر و گسترده‌تر از اخبار درست پخش می‌شود. پایه‌ی تجربیِ مدخل ۶۷۴ (مدل اشاعه اطلاعات جعلی). (تأییدشده با Crossref — Science, vol 359, iss 6380, p 1146-1151)', NULL, 'fa', NULL, 'international', '70935d4f17bb3a76fe556b187e3cb4200d84e687f87e09f7b68f2de65eaddc83', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-12', 'article', 'book-new-12', 'new-book-12', 'رسانه‌های اجتماعی و اخبار جعلی در انتخابات ۲۰۱۶', 'Social Media and Fake News in the 2016 Election', 'article', 'پراستنادترین مقاله‌ی اقتصادِ خبرِ جعلی؛ برآورد اثر اخبار جعلی در انتخابات ۲۰۱۶ آمریکا (حدود ۱/۲ رأی) و مکانیزم‌های پخش آن در شبکه‌های اجتماعی. پایه‌ی اقتصادیِ مدخل ۵۳۰ و ۶۷۴. (تأییدشده با Crossref — JEP, vol 31, iss 2, p 211-236)', NULL, 'fa', NULL, 'international', 'a517833add90e33527dc662217c1d225276f7104dc272cc63114b284079993af', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-13', 'article', 'book-new-13', 'new-book-13', 'مواجهه با اخبار و نظرات ایدئولوژیک متنوع در فیس‌بوک', 'Exposure to ideologically diverse news and opinion on Facebook', 'article', 'آزمایش‌محورترین مقاله‌ی «اتاق پژواک»؛ با استفاده از فیس‌بوک نشان می‌دهد کاربران در فضای آنلاین با طیف ایدئولوژیک تنگ‌تری از اخبار مواجه می‌شوند نسبت به رسانه‌های سنتی. پایه‌ی تجربیِ مدخل ۱۱۳ و ۱۱۲. (تأییدشده با Crossref — Science, vol 348, iss 6239, p 1130-1132)', NULL, 'fa', NULL, 'international', '34b6028aab3f69f2258955ebee3cd0c980a3b7243ff5e4e1a416a78c7989479d', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-14', 'article', 'book-new-14', 'new-book-14', 'نظریه ارتباطات انسانی: مدل پنج‌بُعدی', 'Human communication theory: a five-dimensional model', 'article', 'مهم‌ترین مدل نظریِ «ارتباطات اسلامی/بومی» که توسط یک نظریه‌پرداز ایرانی (مولانا) مطرح شده؛ پنج بُعد: ارتباط خودباخودی، ارتباط با خدا، ارتباط بین‌فردی، ارتباط با طبیعت و ارتباط اجتماعی. منبع اصلیِ مدخل ۲۸۰ (نظریه خودتعیینی) و بافت ایرانی/اسلامی سایت. (تأییدشده با Crossref — JIC, vol 25, iss 1, p 3-33)', NULL, 'fa', NULL, 'iranian', 'e74c8bdf09ede3a644421f1470c94a3a331756de03743042fbec24b87ae36c41', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-15', 'article', 'book-new-15', 'new-book-15', 'غرب‌زداییِ نظریه رسانه یا شرق‌شناسیِ معکوس: «ارتباطات اسلامی» به‌عنوان نظریه', 'De-Westernizing media theory or reverse orientalism: ''Islamic communication'' as theory', 'article', 'مهم‌ترین مقاله‌ی نظریِ «غرب‌زدایی‌کردنِ نظریه رسانه» از منظر ارتباطات اسلامی؛ استدلال می‌کند «ارتباطات اسلامی» می‌تواند نظریه‌ای مستقل باشد نه صرفاً تطبیق نظریه‌های غربی. منبع اصلیِ مدخل ۹۵ (شرق‌شناسی و نظریه پسااستعماری رسانه). (تأییدشده با Crossref — MCS, vol 25, iss 3, p 415-422)', NULL, 'fa', NULL, 'iranian', '4dfd8c05a526c7ed9fd0f9c6b5e1a4c9a343755ad6b4ce9fb9d33ca47039fbba', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-16', 'book', 'book-new-16', 'new-book-16', 'تاریخ اجتماعی سینمای ایران، جلد ۱: سینمای تخیلات، ۱۹۴۰-۱۹۷۹', 'A Social History of Iranian Cinema, Vol. 1: The Formative Period, 1940-1979', 'book', 'مهم‌ترین اثر تاریخیِ سینمای ایران در ۴ جلد؛ تحلیل بازنمایی هویت، تاریخ و مدرنیته در سینمای ایران. منبع اصلیِ تاریخ رسانه/بازنمایی در بافت ایرانی. (تأییدشده با Crossref — Duke UP, 4 volumes)', NULL, 'fa', NULL, 'iranian', '88596634c38399afb0a5353b247ec6512a08a6331a1d135b65b2adfa684928e9', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-17', 'book', 'book-new-17', 'new-book-17', 'اطلاعات جهانی و ارتباطات جهانی: افق‌های تازه در ارتباطات بین‌المللی', 'Global Information and World Communication: New Frontiers in International Communication', 'book', 'کلاسیکِ ارتباطات بین‌المللی از دیدگاه یک نظریه‌پرداز ایرانی (نسخه‌ی ۱۹۹۷)؛ تحلیل نظم نوین جهانی اطلاعات و ارتباطات و نقش رسانه‌ها در ساخت جهانی‌شدن. منبع اصلیِ مدخل ۴۰۳ (نظم نوین جهانی اطلاعات و ارتباطات) و ۵۱۳ (نظریه نظام جهانی اطلاعات).', NULL, 'fa', NULL, 'iranian', '29b12c3892fe50c1dcc961c0ea57b2100172f0c64301eaf0feabfd5386ebf6b7', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-18', 'book', 'book-new-18', 'new-book-18', 'ارتباطات جهانی در حال گذار: پایان تنوع؟', 'Global Communication in Transition: The End of Diversity?', 'book', 'ادامه‌ی اثر کلاسیکِ مولانا؛ تحلیل گذار در ارتباطات جهانی و پرسش از آینده‌ی تنوع فرهنگی در برابر یکسان‌سازی. منبع اصلیِ مدخل ۴۰۳ و تکمیل‌کننده‌ی ۵۱۳.', NULL, 'fa', NULL, 'iranian', '4cd478f183a1bcc35dfebe29f513e947f2432e1071395e278ec04872dc8c55aa', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-19', 'book', 'book-new-19', 'new-book-19', 'پسا-حقیقت (نسخه‌ی فُلِر — از منظر فلسفه‌ی علم)', 'Post-truth', 'book', 'مهم‌ترین تحلیلِ فلسفه‌ی علمِ پسا-حقیقت؛ Fuller پسا-حقیقت را «استفاده‌ی ابزاری از احساسات و روایت برای شکل‌دهی به حقیقت» تعریف می‌کند. مکملِ نظریِ McIntyre (#4) و d''Ancona (#5) — پراستناد در مطالعات پسا-حقیقت.', NULL, 'fa', NULL, 'international', '8eb9322749bbe9b2c056501bb38837da37cedb50ad965916e582563025d3da26', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00'),
('doc-new-book-20', 'article', 'book-new-20', 'new-book-20', 'بزرگ‌دیگری: سرمایه‌داری نظارتی و چشم‌اندازهای تمدن اطلاعاتی', 'Big other: Surveillance Capitalism and the Prospects of an Informational Civilization', 'article', 'مقاله‌ی بنیادینِ Zuboff (پیش از کتاب #1) که مفهوم «بزرگ‌دیگری» (Big Other) و سرمایه‌داری نظارتی را مطرح کرد؛ پیش‌بینی تمدن اطلاعاتی زیر کنترل نهادهای کنشی. منبع اصلیِ مدخل ۲۷۲ (حکمرانی‌مندی و قدرت زیستی) و ۲۸۵ (داده‌نظارتی). (تأییدشده با Crossref — Journal of Information Technology, 2015)', NULL, 'fa', NULL, 'international', '936a829fe0d8a77a37343a69473f3e767b3db5ae135b87aea694ebb45688ce65', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
