('ref-new-book-2', 'book', 'الگوریتم‌های سرکوب: چگونه موتورهای جستجو نژادپرستی را تقویت می‌کنند', 'Algorithms of Oppression: How Search Engines Reinforce Racism', '["Safiya Umoja Noble"]', 'NYU Press', NULL, 2018, '978-1-4798-3724-3', NULL, NULL, 'https://covers.openlibrary.org/b/id/12856940-L.jpg', 'S. Noble (2018). Algorithms of Oppression: How Search Engines Reinforce Racism. NYU Press.', '["https://covers.openlibrary.org/b/id/12856940-L.jpg", "https://nyu.press/9781479892617"]', 'verified', NOW(), NOW()),
